    <script>
    document.addEventListener('DOMContentLoaded',()=>{
        const form=document.getElementById('post-editor-form'),title=document.getElementById('title'),slug=document.getElementById('slug'),editor=document.getElementById('content-editor'),content=document.getElementById('content'),fileInput=document.querySelector('[data-editor-file]'),featured=document.getElementById('featured_image');
        let slugEdited=Boolean(slug.value); const slugify=value=>value.toLowerCase().normalize('NFKD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'');
        slug.addEventListener('input',()=>{slugEdited=true;updatePreview()});title.addEventListener('input',()=>{if(!slugEdited)slug.value=slugify(title.value);updatePreview()});
        const previewTitle=document.querySelector('[data-preview-title]'),previewDescription=document.querySelector('[data-preview-description]'),previewSlug=document.querySelector('[data-preview-slug]'),metaTitle=document.getElementById('meta_title'),metaDescription=document.getElementById('meta_description');
        const updatePreview=()=>{previewTitle.textContent=metaTitle.value||title.value||'Your post title';previewDescription.textContent=metaDescription.value||document.getElementById('excerpt').value||'Your post description will appear here, helping readers decide to visit your story.';previewSlug.textContent=slug.value||'your-story'};
        [['meta_title',60],['meta_description',160]].forEach(([id,target])=>{const input=document.getElementById(id),counter=document.querySelector(`[data-counter="${id}"]`);const update=()=>{counter.textContent=`${input.value.length} / ${target}`;counter.classList.toggle('counter-over',input.value.length>target);updatePreview()};input.addEventListener('input',update);update()});
        document.querySelectorAll('[data-editor-command]').forEach(button=>button.addEventListener('click',()=>{editor.focus();document.execCommand(button.dataset.editorCommand,false,button.dataset.editorValue||null)}));
        document.querySelectorAll('[data-editor-block]').forEach(button=>button.addEventListener('click',()=>{editor.focus();document.execCommand('formatBlock',false,button.dataset.editorBlock)}));
        document.querySelector('[data-editor-link]').addEventListener('click',()=>{const url=prompt('Enter a link URL');if(url){editor.focus();document.execCommand('createLink',false,url)}});
        document.querySelector('[data-editor-image]').addEventListener('click',()=>fileInput.click());
        fileInput.addEventListener('change',async()=>{if(!fileInput.files[0])return;const body=new FormData();body.append('image',fileInput.files[0]);try{const response=await fetch('{{ route('admin.blog.editor-image') }}',{method:'POST',headers:{'X-CSRF-TOKEN':document.querySelector('meta[name="csrf-token"]').content,'Accept':'application/json'},body});if(!response.ok)throw new Error('Upload failed');const result=await response.json();editor.focus();const image=document.createElement('img');image.src=result.url;image.alt='';const selection=window.getSelection();if(selection.rangeCount)selection.getRangeAt(0).insertNode(image);else editor.append(image)}catch(error){alert('Image upload failed. Check that storage is linked and try again.')}finally{fileInput.value=''}});
        featured.addEventListener('change',()=>{const file=featured.files[0];if(!file)return;const image=document.querySelector('[data-featured-preview]'),placeholder=document.querySelector('[data-upload-placeholder]');image.src=URL.createObjectURL(file);image.hidden=false;if(placeholder)placeholder.hidden=true});
        form.addEventListener('submit',event=>{content.value=editor.innerHTML;if(!editor.textContent.trim()){event.preventDefault();editor.focus();alert('Please add your article content before saving.')}});
        document.getElementById('excerpt').addEventListener('input',updatePreview);updatePreview();
    });
    </script>
